}

pub fn printUnwindError(debug_info: *std.debug.SelfInfo, out_stream: *std.Io.Writer, address: usize, e: std.debug.UnwindError, tty_config: std.io.tty.Config) !void {
        if ((!bun.Environment.isDebug)) {
            _ = unreachable;
        }
        const module_name = ((debug_info.getModuleNameForAddress(address)) orelse ("???"));
        _ = try tty_config.setColor(out_stream, .dim);
        if ((e == error.MissingDebugInfo)) {
            _ = try out_stream.print("Unwind information for `{s}:0x{x}` was not available, trace may be incomplete\n\n", .{ module_name, address });
        } else {
            _ = try out_stream.print("Unwind error at address `{s}:0x{x}` ({}), trace may be incomplete\n\n", .{ module_name, address, e });
        }
        _ = try tty_config.setColor(out_stream, .reset);
}
